   595→        async function loadProjectSessions(project, pushState = true) {
   596→            currentProject = project;
   597→            currentConversation = null;
   598→            listContainer.innerHTML = '<div class="loading">Loading...</div>';
   599→            searchBox.value = '';
   600→            try {
   601→                let sessions;
   602→                // Try to get sessions from cached index (static mode)
   603→                if (indexData) {
   604→                    const projectData = indexData.projects.find(p => p.name === project);
   605→                    sessions = projectData ? projectData.sessions : [];
   606→                } else {
   607→                    // Fall back to server API
   608→                    const response = await fetch(`/api/sessions?project=${encodeURIComponent(project)}`);
   609→                    sessions = await response.json();
   610→                }
   611→                renderSessionsList(sessions);
   612→                if (pushState) updateUrl();
   613→            } catch (e) {
   614→                listContainer.innerHTML = '<div class="empty-state"><p>Failed to load</p></div>';
   615→            }
   616→        }
   617→
   618→        function goBackToProjects() {
   619→            currentProject = null;
   620→            currentConversation = null;
   621→            searchBox.value = '';
   622→            renderProjectsList();
   623→            updateUrl();
   624→        }
   625→
   626→        function renderProjectsList(filter = '') {
   627→            const filtered = projects.filter(p =>
   628→                p.name.toLowerCase().includes(filter.toLowerCase())
   629→            );
   630→
   631→            if (filtered.length === 0) {
   632→                listContainer.innerHTML = '<div class="empty-state"><p>No projects</p></div>';
   633→                return;
   634→            }
   635→
   636→            let html = `<div class="list-header">Projects (${filtered.length})</div>`;
   637→            html += filtered.map(p => {
   638→                // Format: -Users-htong-Desktop-projectname
   639→                // Extract just the last folder name after Desktop (or last segment)
   640→                const match = p.name.match(/-Desktop-(.+)$/);
   641→                const projectName = match ? match[1].replace(/-/g, '-') : p.name.split('-').pop();
   642→                return `
   643→                    <div class="project-item" onclick="loadProjectSessions('${p.name}')">
   644→                        <div class="project-name">
   645→                            ${projectName}
   646→                            <span class="count-badge">${p.sessionCount}</span>
   647→                        </div>
   648→                    </div>
   649→                `;
   650→            }).join('');
   651→
   652→            listContainer.innerHTML = html;
   653→        }
   654→
   655→        function renderSessionsList(sessions) {
   656→            let html = `
   657→                <div class="back-btn" onclick="goBackToProjects()">Back</div>
   658→                <div class="list-header">Sessions (${sessions.length})</div>
   659→            `;
   660→
   661→            if (sessions.length === 0) {
   662→                html += '<div class="empty-state"><p>No sessions</p></div>';
   663→            } else {
   664→                html += sessions.map(s => {
   665→                    const d = new Date(s.modified * 1000);
   666→                    const dateStr = d.toLocaleDateString(undefined, {month: 'short', day: 'numeric'});
   667→                    const timeStr = d.toLocaleTimeString(undefined, {hour: '2-digit', minute: '2-digit'});
   668→                    const displayName = s.summary || s.name.replace('.jsonl', '').slice(0, 20);
   669→                    return `
   670→                        <div class="session-item" onclick="loadConversation('${s.path}')">
   671→                            <div class="session-name">${displayName}</div>
   672→                            <div class="session-meta">${dateStr}, ${timeStr}</div>
   673→                        </div>
   674→                    `;
   675→                }).join('');
   676→            }
   677→
   678→            listContainer.innerHTML = html;
   679→        }
   680→
   681→        async function loadConversation(filePath, pushState = true) {
   682→            messagesContainer.innerHTML = '<div class="loading">Loading...</div>';
   683→            try {
   684→                let content;
   685→                // Try direct file fetch first (static mode), fall back to API
   686→                if (indexData) {
   687→                    const response = await fetch(filePath);
   688→                    content = await response.text();
   689→                } else {
   690→                    const response = await fetch(`/api/conversation?file=${encodeURIComponent(filePath)}`);
   691→                    content = await response.text();
   692→                }
   693→                parseConversation(filePath, content);
   694→                renderConversation();
   695→                if (pushState) updateUrl();
   696→            } catch (e) {
   697→                messagesContainer.innerHTML = '<div class="empty-state"><p>Failed to load</p></div>';
   698→            }
   699→        }
   700→
   701→        function parseConversation(filename, content) {
   702→            const lines = content.trim().split('\n');
   703→            const messages = [];
   704→            let summary = '';
   705→            let sessionId = '';
   706→            let gitBranch = '';
   707→            let agentId = '';
   708→            let isAgent = filename.includes('agent-');
   709→
   710→            lines.forEach(line => {
   711→                try {
   712→                    const obj = JSON.parse(line);
   713→                    if (obj.type === 'summary') {
   714→                        summary = obj.summary;
   715→                    } else if (obj.type === 'user' || obj.type === 'assistant') {
   716→                        if (!sessionId && obj.sessionId) sessionId = obj.sessionId;
   717→                        if (!gitBranch && obj.gitBranch) gitBranch = obj.gitBranch;
   718→                        if (!agentId && obj.agentId) agentId = obj.agentId;
   719→
   720→                        // Skip internal "Warmup" messages in agent sessions
   721→                        if (isAgent && obj.type === 'user' && obj.message?.content === 'Warmup') {
   722→                            return;
   723→                        }
   724→                        messages.push(obj);
   725→                    } else if (obj.type === 'system') {
   726→                        messages.push(obj);
   727→                    }
   728→                } catch (e) {}
   729→            });
   730→
   731→            const id = filename.split('/').pop().replace('.jsonl', '');
   732→            currentConversation = id;
   733→            conversations[id] = { filename, summary, sessionId, gitBranch, agentId, isAgent, messages };
   734→        }
   735→
   736→        function renderConversation() {
   737→            const conv = conversations[currentConversation];
   738→            if (!conv) return;
   739→
   740→            conversationHeader.style.display = 'flex';
   741→
   742→            document.getElementById('conversationTitle').textContent = conv.summary || conv.filename.split('/').pop();
   743→            document.getElementById('conversationMeta').textContent = conv.gitBranch ? `Branch: ${conv.gitBranch}` : '';
   744→
   745→            renderMessages();
   746→        }
   747→
   748→        function renderMessages() {
   749→            const conv = conversations[currentConversation];
   750→            if (!conv) return;
   751→
   752→            const showUser = document.getElementById('showUser').checked;
   753→            const showAssistant = document.getElementById('showAssistant').checked;
   754→            const showTools = document.getElementById('showTools').checked;
   755→            const showSystem = document.getElementById('showSystem').checked;
   756→
   757→            const filtered = conv.messages.filter(m => {
   758→                // Tool results come as type: "user" but should be filtered with Tools
   759→                const isToolResult = m.type === 'user' &&
   760→                    Array.isArray(m.message?.content) &&
   761→                    m.message.content.some(c => c.type === 'tool_result');
   762→
   763→                if (isToolResult) return showTools;
   764→                if (m.type === 'user') return showUser;
   765→                if (m.type === 'assistant') return showAssistant;
   766→                if (m.type === 'system') return showSystem;
   767→                return true;
   768→            });
   769→
   770→            messagesContainer.innerHTML = filtered.map(msg => renderMessage(msg, showTools)).join('');
   771→        }
   772→
   773→        function renderMessage(msg, showTools) {
   774→            const time = msg.timestamp ? new Date(msg.timestamp).toLocaleTimeString(undefined, {hour: '2-digit', minute: '2-digit'}) : '';
   775→
   776→            // Check if this is a tool_result message (comes as type: "user" but is really tool output)
   777→            const isToolResult = msg.type === 'user' &&
   778→                Array.isArray(msg.message?.content) &&
   779→                msg.message.content.some(c => c.type === 'tool_result');
   780→
   781→            const role = isToolResult ? 'tool' : (msg.type === 'user' ? 'user' : (msg.type === 'assistant' ? 'assistant' : 'system'));
   782→
   783→            let content = '';
   784→
   785→            // Handle system messages (different structure)
   786→            if (msg.type === 'system') {
   787→                const parts = [];
   788→                if (msg.subtype) parts.push(`[${msg.subtype}]`);
   789→                if (msg.hookInfos && msg.hookInfos.length > 0) {
   790→                    parts.push(`Hooks: ${msg.hookInfos.map(h => h.command).join(', ')}`);
   791→                }
   792→                if (msg.stopReason) parts.push(`Stop: ${msg.stopReason}`);
   793→                if (msg.level) parts.push(`Level: ${msg.level}`);
   794→                content = escapeHtml(parts.join(' | ') || 'System event');
   795→            } else if (msg.message) {
   796→                if (typeof msg.message.content === 'string') {
   797→                    content = escapeHtml(msg.message.content);
   798→                } else if (Array.isArray(msg.message.content)) {
   799→                    content = msg.message.content.map(c => {
   800→                        if (c.type === 'text') {
   801→                            return escapeHtml(c.text);
   802→                        } else if (c.type === 'image' && c.source) {
   803→                            // Handle base64 images
   804→                            const src = c.source.type === 'base64'
   805→                                ? `data:${c.source.media_type};base64,${c.source.data}`
   806→                                : c.source.url;
   807→                            return `<div class="image-container"><img class="message-image" src="${src}" alt="Image"></div>`;
   808→                        } else if (c.type === 'tool_use' && showTools) {
   809→                            return renderToolUse(c);
   810→                        } else if (c.type === 'tool_result' && showTools) {
   811→                            return renderToolResult(c);
   812→                        }
   813→                        return '';
   814→                    }).join('');
   815→                }
   816→            }
   817→
   818→            if (!content.trim()) return '';
   819→
   820→            // Build tooltip data with ALL non-id attributes
   821→            const tooltipData = {};
   822→            if (msg.message?.model) tooltipData.model = msg.message.model;
   823→            if (msg.agentId) tooltipData.agent = msg.agentId;
   824→            if (msg.gitBranch) tooltipData.branch = msg.gitBranch;
   825→            if (msg.version) tooltipData.version = msg.version;
   826→            if (msg.isSidechain !== undefined) tooltipData.sidechain = msg.isSidechain;
   827→            if (msg.cwd) tooltipData.cwd = msg.cwd;
   828→            if (msg.userType) tooltipData.userType = msg.userType;
   829→            if (msg.message?.stop_reason) tooltipData.stop_reason = msg.message.stop_reason;
   830→            if (msg.message?.usage) {
   831→                const u = msg.message.usage;
   832→                tooltipData.tokens = `in:${u.input_tokens || 0} out:${u.output_tokens || 0}`;
   833→                if (u.cache_read_input_tokens) tooltipData.cache_read = u.cache_read_input_tokens;
   834→                if (u.cache_creation_input_tokens) tooltipData.cache_create = u.cache_creation_input_tokens;
   835→            }
   836→            if (msg.parentUuid) tooltipData.parent = msg.parentUuid;
   837→            if (msg.requestId) tooltipData.request = msg.requestId;
   838→
   839→            const uuid = msg.uuid || '';
   840→            const selectedClass = currentMessage === uuid ? ' selected' : '';
   841→
   842→            // Check if content is only tool calls (no text)
   843→            let isToolsOnly = false;
   844→            if (Array.isArray(msg.message?.content)) {
   845→                const hasText = msg.message.content.some(c => c.type === 'text' && c.text?.trim());
   846→                const hasTools = msg.message.content.some(c => c.type === 'tool_use' || c.type === 'tool_result');
   847→                isToolsOnly = hasTools && !hasText;
   848→            }
   849→            const toolsOnlyClass = isToolsOnly ? ' tools-only' : '';
   850→
   851→            return `
   852→                <div class="message ${role}${selectedClass}" data-tooltip='${JSON.stringify(tooltipData)}' data-uuid="${uuid}">
   853→                    <div class="message-header">
   854→                        <span class="message-role ${role}">${role}</span>
   855→                        <span class="message-time">${time}</span>
   856→                    </div>
   857→                    <div class="message-content${toolsOnlyClass}">${content}</div>
   858→                </div>
   859→            `;
   860→        }
   861→
   862→        function renderToolUse(toolUse) {
   863→            const input = typeof toolUse.input === 'object'
   864→                ? JSON.stringify(toolUse.input, null, 2)
   865→                : toolUse.input;
   866→
   867→            return `<div class="tool-use"><div class="tool-header">${toolUse.name}</div><div class="tool-input">${escapeHtml(input)}</div></div>`;
   868→        }
   869→
   870→        function renderToolResult(toolResult) {
   871→            let content = '';
   872→
   873→            if (typeof toolResult.content === 'string') {
   874→                content = escapeHtml(toolResult.content);
   875→            } else if (Array.isArray(toolResult.content)) {
   876→                content = toolResult.content.map(c => {
   877→                    if (c.type === 'image' && c.source) {
   878→                        const src = c.source.type === 'base64'
   879→                            ? `data:${c.source.media_type};base64,${c.source.data}`
   880→                            : c.source.url;
   881→                        return `<div class="image-container"><img class="message-image" src="${src}" alt="Image"></div>`;
   882→                    }
   883→                    return c.text ? escapeHtml(c.text) : '';
   884→                }).join('\n');
   885→            }
   886→
   887→            return `<div class="tool-result"><div class="tool-result-header">Output</div><div class="tool-result-content">${content}</div></div>`;
   888→        }
   889→
   890→        function escapeHtml(text) {
   891→            if (!text) return '';
   892→            const div = document.createElement('div');
   893→            div.textContent = text;
   894→            return div.innerHTML;
   895→        }
   896→
   897→        ['showUser', 'showAssistant', 'showTools', 'showSystem'].forEach(id => {
   898→            document.getElementById(id).addEventListener('change', renderMessages);
   899→        });
   900→
   901→        // Mouse-following tooltip
   902→        const mouseTooltip = document.getElementById('mouseTooltip');
   903→
   904→        document.addEventListener('mousemove', (e) => {
   905→            const msgEl = e.target.closest('.message[data-tooltip]');
   906→            if (msgEl) {
   907→                const data = JSON.parse(msgEl.dataset.tooltip);
   908→                if (Object.keys(data).length > 0) {
   909→                    // Build tooltip content
   910→                    let html = '';
   911→                    for (const [key, value] of Object.entries(data)) {
   912→                        html += `<div class="tooltip-row"><span class="tooltip-key">${key}:</span><span class="tooltip-value">${value}</span></div>`;
   913→                    }
   914→                    mouseTooltip.innerHTML = html;
   915→                    mouseTooltip.style.display = 'block';
   916→
   917→                    // Position near cursor
   918→                    let x = e.clientX + 15;
   919→                    let y = e.clientY + 15;
   920→
   921→                    // Keep tooltip on screen
   922→                    const rect = mouseTooltip.getBoundingClientRect();
   923→                    if (x + rect.width > window.innerWidth) {
   924→                        x = e.clientX - rect.width - 10;
   925→                    }
   926→                    if (y + rect.height > window.innerHeight) {
   927→                        y = e.clientY - rect.height - 10;
   928→                    }
   929→
   930→                    mouseTooltip.style.left = x + 'px';
   931→                    mouseTooltip.style.top = y + 'px';
   932→                } else {
   933→                    mouseTooltip.style.display = 'none';
   934→                }
   935→            } else {
   936→                mouseTooltip.style.display = 'none';
   937→            }
   938→        });
   939→
   940→        document.addEventListener('mouseout', (e) => {
   941→            if (!e.relatedTarget || !document.body.contains(e.relatedTarget)) {
   942→                mouseTooltip.style.display = 'none';
   943→            }
   944→        });
   945→
   946→        // Click on message to select it and update URL
   947→        messagesContainer.addEventListener('click', (e) => {
   948→            const msgEl = e.target.closest('.message[data-uuid]');
   949→            if (msgEl && msgEl.dataset.uuid) {
   950→                // Remove previous selection
   951→                document.querySelectorAll('.message.selected').forEach(el => el.classList.remove('selected'));
   952→                // Select this message
   953→                msgEl.classList.add('selected');
   954→                currentMessage = msgEl.dataset.uuid;
   955→                updateUrl();
   956→            }
   957→        });
   958→
   959→        function scrollToMessage(uuid) {
   960→            const msgEl = document.querySelector(`.message[data-uuid="${uuid}"]`);
   961→            if (msgEl) {
   962→                msgEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
   963→                msgEl.classList.add('selected');
   964→            }
   965→        }
   966→    </script>
   967→</body>
   968→</html>
